  function speechMarkup(q){const extras=isDay4?`<strong>Var ligger Vitsand?</strong> —¿Dónde está Vitsand?—.<br><strong>Tack så mycket.</strong> —Muchas gracias—.`:isDay3?`<strong>Var ligger slottet?</strong> —¿Dónde está el castillo?—.<br><strong>Tack så mycket.</strong> —Muchas gracias—.`:`<strong>En kaffe, tack.</strong> —Un café, por favor—.<br><strong>Kan vi få notan, tack?</strong> —¿Nos trae la cuenta, por favor?—.`;return `<div class="speech-card"><button class="flashcard" id="flip-card" type="button"><span class="flash-front-speech"><small>TOCA PARA GIRAR</small><strong>${q.word}</strong></span><span class="flash-back-speech"><small>EN ESPAÑOL</small><strong>${q.meaning}</strong><em>${q.tip}</em></span></button><div class="speech-controls"><button id="listen-model" type="button">▶ Escuchar modelo</button><button id="record-voice" type="button">● Grabar mi voz</button><button id="play-record" type="button" ${recordUrl?"":"disabled"}>▶ Mi grabación</button></div><p class="fine">No hay nota automática. Si el micrófono no está disponible, puedes continuar.</p><details class="dossier"><summary>OTRAS FRASES ÚTILES</summary><p>${extras}</p></details></div>`}
