  function correctionIntro(){const count=state.failedKeys.length,secured=state.balance>=300;setChrome({correction:true,progress:100});screen.className="screen dark";if(isV7Day3){screen.innerHTML=`<p class="kicker">DÍA ${DAY} · REPASO</p><h1>El informe conserva ${count===1?"una respuesta por revisar":`${count} respuestas por revisar`}.</h1><p>Solo reaparecen los retos que necesitaron otro intento. El contexto y las evidencias ya recuperadas permanecen guardados.</p><div class="correction-list">${state.failedKeys.map((id,i)=>`<div class="correction-item"><strong>${i+1}</strong><span>${findQuestion(id).q.title}</span></div>`).join("")}</div>`;setActions([{label:"Continuar sin repasar",kind:"secondary",run:()=>{state.correctionSkipped=true;state.stage="verified";save();render()}},{label:"Repasar los retos",run:()=>{state.stage="correction";save();render()}}],true);return}screen.innerHTML=`<p class="kicker">DÍA ${DAY} · CORRECCIÓN 0 DE ${count}</p><h1>${secured?"El canal ya está asegurado.":"La ruta conserva interferencias."}</h1><p>${count===1?"Solo reaparecerá una clave.":`Solo reaparecerán las ${count} claves que necesitaron otro intento.`} Las demás siguen selladas.</p><div class="correction-list">${state.failedKeys.map((id,i)=>`<div class="correction-item"><strong>${i+1}</strong><span>${findQuestion(id).q.title}</span></div>`).join("")}</div><p>${secured?"Puedes continuar o repararlas para añadir 25 kr a la reserva.":"Repararlas liberará las 25 kr restantes."}</p>`;const a=[];if(secured)a.push({label:"Continuar sin corregir",kind:"secondary",run:()=>{state.correctionSkipped=true;state.stage="verified";save();render()}});a.push({label:secured?"Reparar y ganar 25 kr":"Reparar las claves pendientes",run:()=>{state.stage="correction";save();render()}});setActions(a,true)}
