  function verified(){if(isV7Day3){setChrome({progress:100});screen.className="screen dark center";const pending=state.failedKeys.length-state.correctedKeys.length,status=pending?`${pending} retos quedan disponibles para repasar; el día puede cerrarse.`:"Cruce, sistema económico, reclamación, expansión y consecuencia están recuperados.";screen.innerHTML=`<p class="kicker">OCHO MISIONES COMPLETADAS</p><h1>${META.verifiedTitle}</h1><div class="three-crowns">♛ ♛ ♛</div><p>${status}</p><div class="reward-ledger"><div><span>Misiones</span><strong>${missions.length} de ${missions.length}</strong></div><div><span>Evidencia principal</span><strong>INFORME ENGELBREKT</strong></div></div>`;setActions([{label:META.verifiedAction,run:()=>{state.endingPage=0;state.stage="ending";save();render()}}],true);return}if(!state.correctionSkipped&&!state.awarded.verify){state.balance+=25;state.awarded.verify=25;save()}setChrome({progress:100});screen.className="screen dark center";const recovered=state.completedKeys.length-state.failedKeys.length+state.correctedKeys.length,status=state.correctionSkipped?`${state.failedKeys.length-state.correctedKeys.length} claves quedan sin corregir.`:state.failedKeys.length?"Todas las interferencias han sido retiradas.":"Ruta verificada sin interferencias.";screen.innerHTML=`<p class="kicker">OCHO MISIONES COMPLETADAS</p><h1>${isDay4?"El cuaderno ya separa las cuatro huellas.":isDay3?"La ruta Engelbrekt está completa.":"El nombre de Margareta está limpio."}</h1><div class="three-crowns">♛ ♛ ♛</div><p>${status}</p><div class="reward-ledger"><div><span>Sellado de la ruta</span><strong>${state.correctionSkipped?"omitido":"+25 kr"}</strong></div><div><span>Claves recuperadas</span><strong>${state.correctionSkipped?recovered:30} de 30</strong></div><div><span>Fondo recuperado</span><strong>${state.balance} kr</strong></div></div>`;setActions([{label:"Abrir la transmisión final",run:()=>{state.stage="fundFinal";save();render()}}],true)}
