  function d3CrossroadsMap(){return `<svg class="schematic-map regional" viewBox="0 0 420 280"><rect width="420" height="280" class="schem-land"/><path class="d3-river-wide" d="M0 146Q91 118 210 143T420 137"/><circle class="schem-point" cx="210" cy="142" r="8"/><path class="schem-road" d="M210 142L210 18M210 142L397 70M210 142L226 269M210 142L26 42"/><text class="schem-label" x="224" y="29">BERGSLAGEN · DALARNA</text><text class="schem-label" x="319" y="61">ESTOCOLMO</text><text class="schem-label" x="241" y="258">ÖSTERGÖTLAND</text><text class="schem-label" x="24" y="34">NIDAROS</text><text class="schem-label" x="172" y="172">ÖREBRO</text></svg>`}
  function d3RiverMap(){return `<svg class="schematic-map regional" viewBox="0 0 420 250"><rect width="420" height="250" class="schem-land"/><path class="d3-lake" d="M263 47c74-29 137 11 133 62-20 57-117 65-163 15-19-30-5-60 30-77Z"/><path class="d3-river" d="M38 143Q124 84 220 111Q250 119 281 103"/><circle class="schem-point" cx="202" cy="107" r="7"/><text class="schem-label" x="169" y="85">Örebro</text><path class="schem-arrow" d="M218 111Q250 116 278 104"/><text class="schem-water-label" x="286" y="107">HJÄLMAREN</text><text class="schem-water-label" x="74" y="130">SVARTÅN</text></svg>`}
  function d3HolsteinMap(){return `<svg class="schematic-map regional" viewBox="0 0 420 330" role="img" aria-label="Mapa esquemático del sur de Suecia, Dinamarca y las costas meridionales del mar Báltico"><rect width="420" height="330" class="schem-water"/><path class="schem-land" d="M176 0H326L320 38L332 76L317 111L326 151L309 188L300 228L276 258L231 264L211 231L215 191L198 153L204 114L188 73Z"/><path class="schem-land" d="M54 48H126L136 88L126 126L137 164L124 204L132 247H67L72 208L60 168L69 128L57 90Z"/><g class="schem-islands"><ellipse cx="144" cy="205" rx="12" ry="19"/><ellipse cx="166" cy="222" rx="18" ry="12"/><ellipse cx="193" cy="207" rx="18" ry="16"/></g><path class="schem-land" d="M38 246H228L238 330H27Z"/><path class="schem-land" d="M228 267H420V330H238Z"/><ellipse class="schem-island" cx="342" cy="171" rx="12" ry="33" transform="rotate(9 342 171)"/><ellipse class="schem-island" cx="309" cy="224" rx="5" ry="29" transform="rotate(4 309 224)"/><path d="M67 205L124 205L132 247H67Z" fill="#e4bd57" stroke="#765a17" stroke-width="1.5"/><path d="M67 247H133L140 284H59Z" fill="#c99869" stroke="#765a17" stroke-width="1.5"/><text class="schem-country" x="79" y="82">DINAMARCA</text><text class="schem-label" x="76" y="102">JUTLANDIA</text><text class="schem-label" x="73" y="229">SCHLESWIG</text><text class="schem-label" x="77" y="270">HOLSTEIN</text><text class="schem-country" x="80" y="314">ALEMANIA</text><text class="schem-country" x="300" y="315">POLONIA · POMERANIA</text><text class="schem-country" x="232" y="35">SUECIA</text><circle class="schem-point" cx="265" cy="94" r="6"/><text class="schem-label" x="230" y="78">BERGSLAGEN</text><circle class="schem-point" cx="300" cy="145" r="5"/><text class="schem-label" x="273" y="133">ESTOCOLMO</text><circle class="schem-point" cx="292" cy="225" r="5"/><text class="schem-label" x="263" y="244">KALMAR</text><text class="schem-label" x="316" y="231">ÖLAND</text><text class="schem-label" x="353" y="174">GOTLAND</text><circle class="schem-point" cx="145" cy="284" r="6"/><text class="schem-label" x="151" y="300">LÜBECK · HANSA</text><path class="schem-route" d="M145 284Q226 240 300 145Q286 112 265 94"/><text class="route-distance" x="228" y="205">hierro ↓ · sal ↑</text><text class="schem-water-label" x="13" y="165">MAR DEL NORTE</text><text class="schem-water-label" x="133" y="145">KATTEGAT</text><text class="schem-water-label" x="326" y="74">MAR BÁLTICO</text></svg>`}
  function d3RevoltMap(){return annotatedMap([11,20,58.5,62.5],[["Dalarna",15.6,61.0],["Bergslagen",15.1,60.1],["Örebro",15.21,59.27],["Västerås",16.54,59.61],["Estocolmo",18.07,59.33]],[[15.6,61.0,15.1,60.1,"1434"],[15.1,60.1,15.21,59.27,"castillos"],[15.21,59.27,16.54,59.61,"expansión"]],"Expansión esquemática de la rebelión de 1434")}
