  function d3NapoleonMap(){return annotatedMap([-11,28,36,62],[['ESPAÑA · José I',-3.5,40.2],['FRANCIA',2,47],['WESTFALIA',9.5,52],['DINAMARCA',10,56],['SUECIA · Örebro',15.2,59.3],['NÁPOLES',14.2,40.8],['VARSOVIA',21,52.2]],[[-3.5,40.2,10,56,'División española · 1808'],[2,47,15.2,59.3,'Bernadotte · 1810']],"Europa bajo la influencia napoleónica")}
